ALTER TABLE learning_tasks ADD COLUMN workspace_url TEXT;
ALTER TABLE learning_tasks ADD COLUMN resources_json TEXT NOT NULL DEFAULT '[]';

UPDATE skill_versions SET manifest_json = '{"schemaVersion":2,"outcomes":["Understand how a Mini App works inside Nimiq Pay","Connect a wallet only when the person chooses","Keep the app calm if they cancel"],"prerequisites":["A paired Mac with Truly open","A place to build your Mini App","No previous Nimiq experience needed"],"supportedEnvironments":["Mac","VS Code","Browser"],"estimatedMinutes":30,"steps":[{"id":"provider","title":"Connect your app to Nimiq Pay","summary":"Let Truly guide you through adding the Nimiq connection to your app.","workspaceLink":{"title":"Build your first Mini App","url":"https://nimiq.dev/mini-apps/tutorials/mini-app-tutorial"},"resources":[{"title":"Mini Apps overview","url":"https://nimiq.dev/mini-apps/"}],"challenge":"Show where your app initializes its Nimiq connection.","rubric":["The connection is initialized through the Mini App SDK","No wallet approval opens during page load"]},{"id":"account","title":"Add a clear Connect wallet button","summary":"Ask for wallet access only after the person chooses to connect.","workspaceLink":{"title":"Nimiq provider reference","url":"https://nimiq.dev/mini-apps/api-reference/nimiq-provider"},"resources":[{"title":"Mini App tutorial","url":"https://nimiq.dev/mini-apps/tutorials/mini-app-tutorial"}],"challenge":"Add a clear action that requests wallet access.","rubric":["The request follows a visible learner action","The interface explains what will happen"]},{"id":"recovery","title":"Make cancellation feel safe","summary":"Keep the app useful when someone closes or declines the wallet request.","workspaceLink":{"title":"Load and test a local Mini App","url":"https://nimiq.dev/mini-apps/development/load-local-mini-app"},"resources":[],"challenge":"Cancel the wallet request and keep the app usable.","rubric":["Cancellation creates no connected state","The learner can try again"]}]}' WHERE id = 'version_nimiq_first_mini_app_1';

UPDATE skill_versions SET manifest_json = '{"schemaVersion":2,"outcomes":["Show NIM prices clearly","Let people review a payment before approving","Unlock access only after payment is confirmed"],"prerequisites":["A paired Mac with Truly open","A Nimiq Pay test account","A checkout screen to practise with"],"supportedEnvironments":["Mac","VS Code","Browser"],"estimatedMinutes":35,"steps":[{"id":"price","title":"Set a clear price","summary":"Show the amount in a way people can understand at a glance.","workspaceLink":{"title":"Nimiq provider reference","url":"https://nimiq.dev/mini-apps/api-reference/nimiq-provider"},"resources":[],"challenge":"Represent a NIM amount without floating-point ambiguity.","rubric":["The displayed amount maps to integer Luna"]},{"id":"preview","title":"Show a simple payment review","summary":"Let people check what they are paying and who receives it before approval.","workspaceLink":{"title":"Nimiq provider reference","url":"https://nimiq.dev/mini-apps/api-reference/nimiq-provider"},"resources":[],"challenge":"Present the asset, amount and recipient before approval.","rubric":["The learner can review all payment details"]},{"id":"submit","title":"Confirm before unlocking","summary":"Wait for a successful payment before giving access to the Path.","workspaceLink":{"title":"Nimiq provider reference","url":"https://nimiq.dev/mini-apps/api-reference/nimiq-provider"},"resources":[],"challenge":"Keep access locked until settlement is independently confirmed.","rubric":["A wallet callback alone cannot unlock access"]}]}' WHERE id = 'version_nim_payments_1';

UPDATE skill_versions SET manifest_json = '{"schemaVersion":2,"outcomes":["Offer NIM and USDT as clear choices","Prepare USDT on the right network","Unlock access only after payment is confirmed"],"prerequisites":["A paired Mac with Truly open","A Nimiq Pay account","A checkout screen to practise with"],"supportedEnvironments":["Mac","VS Code","Browser"],"estimatedMinutes":45,"steps":[{"id":"assets","title":"Offer both payment choices","summary":"Present NIM and USDT clearly so people can choose with confidence.","workspaceLink":{"title":"Using EVM tokens","url":"https://nimiq.dev/mini-apps/features/evm-tokens"},"resources":[{"title":"Nimiq provider reference","url":"https://nimiq.dev/mini-apps/api-reference/nimiq-provider"}],"challenge":"Present NIM and USDT as distinct payment choices.","rubric":["Each asset shows its own amount and network"]},{"id":"chain","title":"Prepare the USDT payment","summary":"Help the wallet use the right network before asking for approval.","workspaceLink":{"title":"Using EVM tokens","url":"https://nimiq.dev/mini-apps/features/evm-tokens"},"resources":[],"challenge":"Prepare USDT on the intended supported chain.","rubric":["The chain is explicit","USDT uses six decimals"]},{"id":"settlement","title":"Confirm before unlocking","summary":"Wait for a successful payment before giving access to the Path.","workspaceLink":{"title":"Using EVM tokens","url":"https://nimiq.dev/mini-apps/features/evm-tokens"},"resources":[],"challenge":"Validate the successful transfer before unlocking.","rubric":["Token, chain, sender, recipient and amount are verified"]}]}' WHERE id = 'version_dual_asset_checkout_1';
